import axios from 'axios';
import React, { useState } from 'react'
import "../App.css";
const Login = ({token,SetToken}) => {
  const [userName,setUsername]=useState("");
  const [password,setPassword]=useState("");
  const [error,setError]=useState("");
  
  const loginHandler = () => {
    setPassword("");
    setUsername("");
    setError("");
  
    axios({
      url: "https://fakestoreapi.com/auth/login",  // Make sure this URL is correct
      method: "POST",
      data: {
        username: userName,
        password: password,
      },
    })
      .then((res) => {
        // Ensure res.data exists and contains a token
        if (res && res.data && res.data.token) {
          console.log(res.data.token);
          SetToken(res.data.token);
          localStorage.setItem("userToken", res.data.token);
        } else {
          console.error("Response data is missing or malformed");
          setError("Login failed, please try again.");
        }
      })
      .catch((err) => {
        // Check if the error has a response and log more details
        if (err.response) {
          console.log(err.response);
          setError(err.response.data.message || "Something went wrong");
        } else {
          console.error("Network or server error:", err);
          setError("Network or server error, please try again later.");
        }
      });
  

  };






  return(

   <div className="login">
  
<div className='login-inputs'>

<input 
value={userName} 
onChange={(e) =>setUsername(e.target.value)}
 type="text" placeholder="Username" />

<input value={password} 
onChange={(e) =>setPassword(e.target.value)}
 type="password" placeholder="Password"/>


{error && <small>{error}</small>}
  <button onClick={loginHandler}>Login</button>
  </div>
  
  
    </div>
  )
};

export default Login
